    ('d0000000-0000-4000-8000-000000000007', 'Bata silikat berpori'                          , 'dinding', 0.11, 5, 3, 30,  62, 'EPD generik pabrikan regional — perkiraan literatur (PRD §11.4)', 'Blok kalsium silikat tebal 100 mm + mortar perekat 3 mm', 1),
